// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
        c.SetMinSum(1);
        c.SetLogFile(address(this));
        c.Initialized();
    }

    function testFuzz_property(uint256 newVal, address actor) public {
        vm.assume(actor != address(0));
        vm.prank(actor);
        bool ok;
        try c.SetMinSum(newVal) {
            ok = true;
        } catch {
            ok = false;
        }
        // After initialization, no call to SetMinSum may succeed (MinSum stays frozen).
        assertTrue(!ok && c.MinSum() == 1);
    }
}
